const data = $input.first().json || {};
const workflow = data.workflow || {};
const execution = data.execution || {};
const workflowId = String(workflow.id || 'unknown').slice(0, 100);
const workflowName = String(workflow.name || 'Ukendt workflow').slice(0, 120);
const executionId = String(execution.id || '').slice(0, 100);
const failedNode = String(execution.lastNodeExecuted || 'Ukendt node').slice(0, 120);
const mode = String(execution.mode || data.trigger?.mode || 'production').slice(0, 40);
const now = Date.now();
const cooldownMs = 6 * 60 * 60 * 1000;
const state = $getWorkflowStaticData('global');
const lastSent = Number(state.lastNotifiedAtByWorkflow?.[workflowId] || 0);

// One alert per failing workflow every six hours. The timestamp is written only
// after SMTP succeeds, so a mail failure never suppresses the next attempt.
if (lastSent && now - lastSent < cooldownMs) return [];

const esc = value => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('\"', '&quot;')
  .replaceAll("'", '&#039;');
const localRoot = 'http://127.0.0.1:5678';
const suppliedUrl = String(execution.url || '');
const safeUrl = suppliedUrl.startsWith(`${localRoot}/`)
  ? suppliedUrl
  : `${localRoot}/home/executions`;
const occurredAt = new Intl.DateTimeFormat('da-DK', {
  dateStyle: 'short', timeStyle: 'short', timeZone: 'Europe/Copenhagen'
}).format(new Date());
const subject = `Entropi n8n · ${workflowName} kræver et kig`;
const html = `<div style="background:#141410;padding:28px 18px;font-family:Arial,sans-serif"><div style="max-width:620px;margin:auto;background:#1c1c18;border:1px solid #34342e;padding:24px"><div style="font-size:12px;letter-spacing:.13em;text-transform:uppercase;color:#d79a83;margin-bottom:8px">Entropi Automation</div><h1 style="font-size:23px;line-height:1.2;color:#edeae2;margin:0 0 8px">En automation stoppede</h1><p style="color:#aaa79f;margin:0 0 20px;line-height:1.5">Åbn n8n og gennemgå execution-loggen. Mailen indeholder bevidst ingen rå fejltekst, payloads eller atletdata.</p><div style="padding:10px 0;border-top:1px solid #34342e;color:#edeae2"><strong>${esc(workflowName)}</strong><div style="font-size:13px;line-height:1.6;color:#aaa79f;margin-top:4px">Node: ${esc(failedNode)} · Kørsel: ${esc(executionId || 'ukendt')} · Mode: ${esc(mode)} · ${esc(occurredAt)}</div></div><a href="${esc(safeUrl)}" style="display:inline-block;margin-top:18px;background:#c8923a;color:#141410;text-decoration:none;font-weight:700;padding:11px 16px;border-radius:3px">Åbn execution-loggen</a><p style="font-size:11px;color:#68665f;margin:22px 0 0">Automatisk fejlmonitor · højst én mail pr. workflow hver 6. time</p></div></div>`;

return [{ json: {
  recipient: 'coach@entropicoaching.dk',
  subject,
  html,
  workflowId,
  executionId,
  notifiedAt: now
} }];

const alert = $('Build safe error alert').first().json;
const state = $getWorkflowStaticData('global');
state.lastNotifiedAtByWorkflow = state.lastNotifiedAtByWorkflow || {};
state.lastNotifiedAtByWorkflow[alert.workflowId] = alert.notifiedAt;
return [{ json: {
  recorded: true,
  workflowId: alert.workflowId,
  executionId: alert.executionId,
  notifiedAt: alert.notifiedAt
} }];
